module IceMazeSolver #(\n    parameter ROWS = 4,\n    parameter COLS = 4,\n    parameter CELL_COUNT = ROWS * COLS,\n    parameter DATA_WIDTH = 2,\n    parameter DIST_WIDTH = 5,\n    parameter DIR_COUNT = 4,\n    parameter MAX_CYCLES = 256\n)(\n    input clk,\n    input rst_n,\n    input start,\n    input [CELL_COUNT*DATA_WIDTH-1:0] grid_data,\n    output reg [CELL_COUNT*DIST_WIDTH-1:0] distances_data,\n    output reg done\n);\n    // State encoding\n    localparam [3:0] IDLE = 4'd0, SETUP = 4'd1, CHECK_CELL = 4'd2, CALC_SLIDE = 4'd3,\n               UPDATE = 4'd4, NEXT_DIR = 4'd5, NEXT_CELL = 4'd6, FINISHED = 4'd7;\n    reg [3:0] state;\n    \n    // Grid and distance storage\n    reg [DATA_WIDTH-1:0] grid [0:CELL_COUNT-1];\n    reg [DIST_WIDTH-1:0] dist_array [0:CELL_COUNT-1];\n    reg [DIST_WIDTH-1:0] next_dist [0:CELL_COUNT-1];\n    \n    // Current cell and direction\n    reg [5:0] curr_cell;\n    reg [1:0] curr_dir;\n    reg [7:0] cycle_count;\n    \n    // Slide computation\n    reg [3:0] start_r, start_c;\n    reg [3:0] slide_r, slide_c;\n    reg [5:0] target_idx;\n    reg slide_active;\n    reg slide_done;\n    \n    // Unpack grid_data into array\n    integer gi;\n    always @(*) begin\n        for (gi = 0; gi < CELL_COUNT; gi = gi + 1) begin\n            grid[gi] = grid_data[gi*DATA_WIDTH +: DATA_WIDTH];\n        end\n    end\n    \n    // Helper functions\n    function automatic [3:0] idx_to_row;\n        input [5:0] idx;\n        idx_to_row = idx / COLS;\n    endfunction\n    \n    function automatic [3:0] idx_to_col;\n        input [5:0] idx;\n        idx_to_col = idx % COLS;\n    endfunction\n    \n    function automatic [5:0] coord_to_idx;\n        input [3:0] r, c;\n        coord_to_idx = r * COLS + c;\n    endfunction\n    \n    // Slide computation logic\n    always @(*) begin\n        slide_done = 1'b0;\n        target_idx = coord_to_idx(slide_r, slide_c);\n        \n        if (slide_active) begin\n            case (curr_dir)\n                2'b00: begin if (slide_r == 4'd0) slide_done = 1'b1; end // Up\n                2'b01: begin if (slide_r == ROWS-1) slide_done = 1'b1; end // Down\n                2'b10: begin if (slide_c == 4'd0) slide_done = 1'b1; end // Left\n                2'b11: begin if (slide_c == COLS-1) slide_done = 1'b1; end // Right\n            endcase\n            \n            if (!slide_done) begin\n                case (curr_dir)\n                    2'b00: target_idx = coord_to_idx(slide_r - 1'b1, slide_c);\n                    2'b01: target_idx = coord_to_idx(slide_r + 1'b1, slide_c);\n                    2'b10: target_idx = coord_to_idx(slide_r, slide_c - 1'b1);\n                    2'b11: target_idx = coord_to_idx(slide_r, slide_c + 1'b1);\n                endcase\n                \n                if (target_idx < CELL_COUNT) begin\n                    case (grid[target_idx])\n                        2'b00: slide_done = 1'b1; // Obstacle\n                        2'b01, 2'b11: slide_done = 1'b1; // Gravel or goal\n                        2'b10: slide_done = 1'b0; // Ice (continue sliding)\n                    endcase\n                end\n            end\n        end\n    end\n    \n    // Main state machine\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            slide_active <= 1'b0;\n            \n            for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                dist_array[i] <= {DIST_WIDTH{1'b1}};\n                next_dist[i] <= {DIST_WIDTH{1'b1}};\n            end\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SETUP;\n                    end\n                end\n                \n                SETUP: begin\n                    for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                        next_dist[i] <= {DIST_WIDTH{1'b1}};\n                        if (grid[i] == 2'b11) begin // Goal cell\n                            dist_array[i] <= {DIST_WIDTH{1'b0}};\n                            next_dist[i] <= {DIST_WIDTH{1'b0}};\n                        end\n                        else begin\n                            dist_array[i] <= {DIST_WIDTH{1'b1}};\n                        end\n                    end\n                    curr_cell <= 6'd0;\n                    curr_dir <= 2'd0;\n                    state <= CHECK_CELL;\n                    cycle_count <= 8'd0;\n                end\n                \n                CHECK_CELL: begin\n                    if (curr_cell < CELL_COUNT && cycle_count < MAX_CYCLES) begin\n                        if (dist_array[curr_cell] != {DIST_WIDTH{1'b1}}) begin\n                            start_r <= idx_to_row(curr_cell);\n                            start_c <= idx_to_col(curr_cell);\n                            state <= CALC_SLIDE;\n                        end\n                        else begin\n                            state <= NEXT_DIR;\n                        end\n                    end\n                    else begin\n                        state <= FINISHED;\n                    end\n                end\n                \n                CALC_SLIDE: begin\n                    slide_r <= start_r;\n                    slide_c <= start_c;\n                    slide_active <= 1'b1;\n                    state <= UPDATE;\n                end\n                \n                UPDATE: begin\n                    slide_active <= 1'b0;\n                    if (dist_array[curr_cell] != {DIST_WIDTH{1'b1}} && target_idx < CELL_COUNT) begin\n                        if (dist_array[target_idx] > (dist_array[curr_cell] + 1)) begin\n                            next_dist[target_idx] <= dist_array[curr_cell] + {{DIST_WIDTH-1{1'b0}}, 1'b1};\n                        end\n                    end\n                    state <= NEXT_DIR;\n                end\n                \n                NEXT_DIR: begin\n                    if (curr_dir < DIR_COUNT - 1) begin\n                        curr_dir <= curr_dir + 1'b1;\n                        state <= CHECK_CELL;\n                    end\n                    else begin\n                        curr_dir <= 2'd0;\n                        state <= NEXT_CELL;\n                    end\n                end\n                \n                NEXT_CELL: begin\n                    curr_cell <= curr_cell + 1'b1;\n                    cycle_count <= cycle_count + 1'b1;\n                    for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                        dist_array[i] <= next_dist[i];\n                    end\n                    state <= CHECK_CELL;\n                end\n                \n                FINISHED: begin\n                    for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                        distances_data[i*DIST_WIDTH +: DIST_WIDTH] <= dist_array[i];\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule